        OrderStatus status = OrderStatus.valueOf(sc.next());
        long requestedId = sc.nextLong();
        long actorId = sc.nextLong();
        Order initial = exists ? new Order(storedId, ownerId, status) : null;
        InMemoryOrderRepository repository = new InMemoryOrderRepository(initial);
        String result = new OrderService(repository).cancel(requestedId, actorId);
        String current = repository.current().map(o -> o.status().name()).orElse("NONE");
