import java.util.*;

enum OrderStatus { NEW, PAID, CANCELLED }

class State {
    OrderStatus status;
    final List<String> outbox = new ArrayList<>();
    final Map<String, String> processed = new HashMap<>();

    State(OrderStatus status) {
        this.status = status;
    }
}

class CancelApplication {
    String cancel(State state, String key, boolean eventWriteFails) {
        if (state.processed.containsKey(key)) return "DUPLICATE";
        if (state.status == OrderStatus.CANCELLED) return "ALREADY_CANCELLED";
        if (state.status == OrderStatus.PAID) return "CONFLICT";
        if (eventWriteFails) return "ROLLBACK";
        state.status = OrderStatus.CANCELLED;
        state.outbox.add("OrderCancelled:" + key);
        state.processed.put(key, "CANCELLED");
        return "CANCELLED";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        State state = new State(OrderStatus.valueOf(sc.next()));
        boolean eventWriteFails = sc.nextInt() == 1;
        int n = sc.nextInt();
        CancelApplication app = new CancelApplication();
        List<String> results = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            results.add(app.cancel(state, sc.next(), eventWriteFails));
        }
        System.out.println("results=" + String.join(",", results));
        System.out.println("status=" + state.status);
        System.out.println("events=" + state.outbox.size());
        System.out.println("processed=" + state.processed.size());
    }
}

