import java.util.*;

record ChangeResult(int status, String code, int version, int outbox) { }

public class Main {
    static ChangeResult change(boolean knownKey, int version, int expectedVersion,
                               String status, boolean eventWriteFails) {
        if (knownKey) return new ChangeResult(200, "duplicate", version, 0);
        if (version != expectedVersion) return new ChangeResult(409, "version_conflict", version, 0);
        if (!status.equals("NEW")) return new ChangeResult(409, "order_not_cancellable", version, 0);
        if (eventWriteFails) return new ChangeResult(500, "rollback", version, 0);
        return new ChangeResult(204, "cancelled", version + 1, 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ChangeResult result = change(sc.nextInt() == 1, sc.nextInt(), sc.nextInt(),
                sc.next(), sc.nextInt() == 1);
        System.out.println(result.status() + " " + result.code());
        System.out.println("version=" + result.version());
        System.out.println("outbox=" + result.outbox());
    }
}

